SELECT ?value WHERE {
  {
    VALUES ?obsType { gemr:ControlOfCorruption gemr:ControlOfCorruptionObservation }
    ?obs rdf:type ?obsType ;
         gemr:hasCountry ?country ;
         gemr:hasYear ?year ;
         gemr:observationValue ?value .
    ?country gemr:countryName "Brazil" .
    ?year gemr:yearValue "2020" .
  }
  UNION
  {
    ?rs rdf:type gemr:RiskScore ;
        gemr:hasCountry ?country ;
        gemr:hasYear ?year ;
        gemr:controlOfCorruptionScore ?value .
    ?country gemr:countryName "Brazil" .
    ?year gemr:yearValue "2020" .
  }
}

PREFIX gemr: <https://gemr-kg.org/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?year ?privateDefaultRate ?totalRiskScore ?governanceScore ?economicHealthScore ?externalVulnerabilityScore ?contagionRiskScore
WHERE {
  ?country gemr:countryName "Philippines" .

  ?riskScoreObs rdf:type gemr:RiskScore ;
    gemr:hasCountry ?country ;
    gemr:hasYear ?yearNode ;
    gemr:totalRiskScore ?totalRiskScore ;
    gemr:governanceScore ?governanceScore ;
    gemr:economicHealthScore ?economicHealthScore ;
    gemr:externalVulnerabilityScore ?externalVulnerabilityScore ;
    gemr:contagionRiskScore ?contagionRiskScore .

  ?yearNode gemr:yearValue ?year .

  ?defaultObs rdf:type gemr:Observation ;
    gemr:hasCountry ?country ;
    gemr:hasYear ?yearNode ;
    gemr:observationType "PrivateDefaultRate" ;
    gemr:observationValue ?privateDefaultRate .

  FILTER(xsd:integer(?year) >= 2010 && xsd:integer(?year) <= 2023)
}
ORDER BY ?year

PREFIX gemr: <https://gemr-kg.org/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?indicator2008 ?value2008 ?indicator2009 ?value2009
WHERE {
  {
    ?obs2008 a gemr:Observation ;
             gemr:hasCountry ?country2008 ;
             gemr:hasYear ?year2008 ;
             gemr:observationValue ?value2008 .
    ?country2008 gemr:countryName "China" .
    ?year2008 gemr:yearValue "2008" .
    ?obs2008 rdfs:label ?indicator2008 .
    FILTER (
      CONTAINS(LCASE(STR(?indicator2008)), "stock") ||
      CONTAINS(LCASE(STR(?indicator2008)), "equity") ||
      CONTAINS(LCASE(STR(?indicator2008)), "market return") ||
      CONTAINS(LCASE(STR(?indicator2008)), "share price")
    )
  }
  {
    ?obs2009 a gemr:Observation ;
             gemr:hasCountry ?country2009 ;
             gemr:hasYear ?year2009 ;
             gemr:observationValue ?value2009 .
    ?country2009 gemr:countryName "China" .
    ?year2009 gemr:yearValue "2009" .
    ?obs2009 rdfs:label ?indicator2009 .
    FILTER (
      CONTAINS(LCASE(STR(?indicator2009)), "default") ||
      CONTAINS(LCASE(STR(?indicator2009)), "non-performing") ||
      CONTAINS(LCASE(STR(?indicator2009)), "npl") ||
      CONTAINS(LCASE(STR(?indicator2009)), "credit risk")
    )
  }
}
ORDER BY ?indicator2008 ?indicator2009

