SELECT ?value WHERE {
  ?obs a gemr:Observation ;
       gemr:observationValue ?value ;
       gemr:hasCountry ?country ;
       gemr:hasYear ?year .
  ?country gemr:countryName "China" .
  ?year gemr:yearValue "2015" .
  {
    ?obs rdfs:label ?label .
  } UNION {
    ?obs gemr:indicatorName ?label .
  }
