}

PREFIX gemr: <https://gemr-kg.org/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryName (AVG(?score) AS ?avgTotalRiskScore)
WHERE {
  ?riskScore gemr:hasCountry ?country ;
             gemr:hasYear ?year ;
             gemr:totalRiskScore ?score .
  ?country gemr:countryName ?countryName .
  ?year gemr:yearValue ?yearValue .
  FILTER(?yearValue >= "2015" && ?yearValue <= "2023")
}
GROUP BY ?countryName
ORDER BY DESC(?avgTotalRiskScore)

