SELECT ?year ?exchangeRate
WHERE {
  ?observation rdf:type gemr:Observation ;
    gemr:hasCountry ?country ;
    gemr:hasYear ?yearNode ;
    gemr:observationType gemr:RealEffectiveExchangeRate ;
    gemr:observationValue ?exchangeRate .

  ?country gemr:countryName "Thailand" .
  ?yearNode gemr:yearValue ?year .

  FILTER (?year >= "2002"^^xsd:gYear && ?year <= "2023"^^xsd:gYear)
