  FILTER(xsd:integer(?yearValue) >= 2010 && xsd:integer(?yearValue) <= 2020)

  FILTER(
    (bound(?label) && regex(lcase(str(?label)), "private.*default")) ||
    (bound(?indicatorName) && regex(lcase(str(?indicatorName)), "private.*default")) ||
    (bound(?indicatorLabel) && regex(lcase(str(?indicatorLabel)), "private.*default"))
