PREFIX gemr: <https://gemr-kg.org/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?countryName (MAX(xsd:decimal(?value)) AS ?maxPrivateDefaultRate)
WHERE {
  ?obs a gemr:Observation ;
       gemr:observationValue ?value ;
       gemr:hasCountry ?country .
  ?country gemr:countryName ?countryName .

  OPTIONAL { ?obs rdfs:label ?label. }
  OPTIONAL { ?obs gemr:indicatorName ?iname. }
  OPTIONAL { ?obs gemr:indicator ?ind. }

  FILTER(
    (
      bound(?label) &&
      regex(lcase(str(?label)), "private") &&
      regex(lcase(str(?label)), "default")
    ) ||
    (
      bound(?iname) &&
      regex(lcase(str(?iname)), "private") &&
      regex(lcase(str(?iname)), "default")
    ) ||
    (
      bound(?ind) &&
      regex(lcase(str(?ind)), "private") &&
      regex(lcase(str(?ind)), "default")
    )
  )

  FILTER(?countryName IN ("Brazil","China","Mexico","Philippines","Poland","Thailand"))
}
GROUP BY ?countryName
ORDER BY DESC(?maxPrivateDefaultRate)

