       gemr:hasCountry ?country ;
       gemr:hasYear ?yearNode ;
       gemr:observationValue ?privateDefaultRate .

  FILTER (
    EXISTS { ?obs rdfs:label ?l . FILTER regex(str(?l), "private\\s*default\\s*rate", "i") } ||
    EXISTS { ?obs gemr:observationName ?l1 . FILTER regex(str(?l1), "private\\s*default\\s*rate", "i") } ||
