              gemr:indicatorName "Private Default Rate" ;
              gemr:hasCountry ?country ;
              gemr:hasYear ?yPdr2015 ;
              gemr:observationValue ?pdr2015 .
  ?yPdr2015 gemr:yearValue "2015" .

