PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?country ?reer
WHERE {
  ?obs rdf:type gemr:Observation ;
       gemr:hasCountry ?countryNode ;
       gemr:hasYear ?yearNode ;
       gemr:observationValue ?reer .
  ?countryNode gemr:countryName ?country .
  ?yearNode gemr:yearValue "2021" .
  ?obs rdfs:label ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "real effective exchange rate"))
}
ORDER BY ?country

