SELECT ?year ?nextYear ?country ?stockPerformance ?avgDefaultRateNextYear
WHERE {
  ?stockObs rdf:type gemr:Observation ;
    gemr:observationType "stock_market_performance" ;
    gemr:observationValue ?stockPerformance ;
    gemr:hasYear ?yearNode ;
    gemr:hasCountry ?countryNode .

  ?yearNode gemr:yearValue ?year .
  ?countryNode gemr:countryName ?country .

  BIND(xsd:integer(?year) + 1 AS ?nextYearInt)
  BIND(xsd:string(?nextYearInt) AS ?nextYear)

  ?defaultObs rdf:type gemr:Observation ;
    gemr:observationType "private_default_rate" ;
    gemr:observationValue ?defaultRate ;
    gemr:hasYear ?nextYearNode ;
    gemr:hasCountry ?countryNode .

  ?nextYearNode gemr:yearValue ?nextYear .

  BIND(AVG(?defaultRate) AS ?avgDefaultRateNextYear)
}
GROUP BY ?year ?nextYear ?country ?stockPerformance
ORDER BY ?country ?year

