PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?countryName (MAX(?value) AS ?maxPrivateDefaultRate)
WHERE {
  ?obs a gemr:Observation ;
       gemr:hasCountry ?country ;
       gemr:hasYear ?year ;
       gemr:observationValue ?value .
  ?country gemr:countryName ?countryName .
  FILTER(?countryName IN ("Brazil","China","Mexico","Philippines","Poland","Thailand"))

  ?year gemr:yearValue ?yearStr .
  BIND(xsd:integer(?yearStr) AS ?yr)
  FILTER(?yr >= 2002 && ?yr <= 2023)

  OPTIONAL { ?obs rdfs:label ?label }
  OPTIONAL { ?obs gemr:indicatorName ?indName }
  OPTIONAL {
    ?obs gemr:hasIndicator ?indicator .
    OPTIONAL { ?indicator rdfs:label ?indicatorLabel }
    OPTIONAL { ?indicator gemr:indicatorName ?indicatorName }
    OPTIONAL { ?indicator gemr:indicatorCode ?indicatorCode }
  }
  OPTIONAL {
    ?obs a ?obsType .
    FILTER(?obsType != gemr:Observation)
    OPTIONAL { ?obsType rdfs:label ?obsTypeLabel }
  }

  BIND(LCASE(CONCAT(
        STR(COALESCE(?label, "")), " ",
        STR(COALESCE(?indName, "")), " ",
        STR(COALESCE(?indicatorLabel, "")), " ",
        STR(COALESCE(?indicatorName, "")), " ",
        STR(COALESCE(?indicatorCode, "")), " ",
        STR(COALESCE(?obsTypeLabel, ""))
  )) AS ?searchText)

  FILTER(CONTAINS(?searchText, "private default rate") || CONTAINS(?searchText, "private_default_rate"))
}
GROUP BY ?countryName
ORDER BY ?countryName

