PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?countryName ?yearT ?polStabilityValue ?yearT1 ?gdpValueT1
WHERE {
  # Get Political Stability observation in year T
  ?polObs rdf:type gemr:Observation ;
          gemr:hasCountry ?country ;
          gemr:hasYear ?yearNode ;
          gemr:observationValue ?polStabilityValue ;
          gemr:indicatorName ?polIndicator .

  ?country gemr:countryName ?countryName .
  ?yearNode gemr:yearValue ?yearT .

  FILTER(CONTAINS(LCASE(?polIndicator), "political stability"))

  # Only negative political stability values
  FILTER(?polStabilityValue < 0)

  # Compute T+1 year
  BIND(xsd:integer(?yearT) + 1 AS ?yearT1Int)
  BIND(STR(?yearT1Int) AS ?yearT1)

  # Get GDP observation in year T+1
  ?gdpObs rdf:type gemr:Observation ;
          gemr:hasCountry ?country ;
          gemr:hasYear ?yearNodeT1 ;
          gemr:observationValue ?gdpValueT1 ;
          gemr:indicatorName ?gdpIndicator .

  ?yearNodeT1 gemr:yearValue ?yearT1 .

  FILTER(CONTAINS(LCASE(?gdpIndicator), "gdp"))

  # Ensure year T is within valid range so T+1 is also available
  FILTER(xsd:integer(?yearT) >= 2002 && xsd:integer(?yearT) <= 2022)
}
ORDER BY ?countryName ?yearT

