PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?countryName ?yearVal ?stockValue ?gdpValue ?stockIndicator ?gdpIndicator
WHERE {
  ?stockObs a gemr:Observation ;
            gemr:observationValue ?stockValue ;
            gemr:hasCountry ?country ;
            gemr:hasYear ?yearNode .
  ?country gemr:countryName ?countryName .
  ?yearNode gemr:yearValue ?yearVal .
  OPTIONAL { ?stockObs gemr:indicatorName ?stockIndName. }
  OPTIONAL { ?stockObs rdfs:label ?stockLabel. }
  BIND(COALESCE(?stockIndName, ?stockLabel, "") AS ?stockIndicator)

  ?gdpObs a gemr:Observation ;
          gemr:observationValue ?gdpValue ;
          gemr:hasCountry ?country ;
          gemr:hasYear ?nextYearNode .
  ?nextYearNode gemr:yearValue ?nextYearVal .
  OPTIONAL { ?gdpObs gemr:indicatorName ?gdpIndName. }
  OPTIONAL { ?gdpObs rdfs:label ?gdpLabel. }
  BIND(COALESCE(?gdpIndName, ?gdpLabel, "") AS ?gdpIndicator)

  FILTER (?stockObs != ?gdpObs)

  FILTER(regex(?stockIndicator, "stock", "i"))
  FILTER(regex(?gdpIndicator, "gdp|gross domestic", "i"))

  FILTER(xsd:integer(?nextYearVal) = xsd:integer(?yearVal) + 1)
  FILTER(xsd:integer(?yearVal) >= 2002 && xsd:integer(?yearVal) <= 2022)
}
ORDER BY ?countryName ?yearVal

