           gemr:hasCountry ?country ;
           gemr:hasYear ?year2013 ;
           gemr:observationValue ?value2013 ;
           gemr:indicatorName "GDP at market prices (current US$)" .
  ?year2013 gemr:yearValue "2013" .

  ?country gemr:countryName ?countryName .
  FILTER(?countryName = "China")

  BIND(xsd:decimal(?value2013) - xsd:decimal(?value2008) AS ?absoluteChange)
  BIND(((xsd:decimal(?value2013) - xsd:decimal(?value2008)) / xsd:decimal(?value2008)) * 100 AS ?percentChange)
}

