PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?countryName
       (MAX(?v2010) AS ?value2010)
       (MAX(?v2020) AS ?value2020)
       ((MAX(?v2020) - MAX(?v2010)) AS ?change)
WHERE {
  ?obs rdf:type gemr:Observation ;
       gemr:hasCountry ?country ;
       gemr:hasYear ?year ;
       gemr:observationValue ?value .
  ?country gemr:countryName ?countryName .
  FILTER(?countryName = "Mexico")
  ?year gemr:yearValue ?yearStr .
  BIND(xsd:integer(?yearStr) AS ?yearNum)
  FILTER(?yearNum IN (2010, 2020))

  OPTIONAL { ?obs gemr:indicatorName ?indName . }
  OPTIONAL { ?obs gemr:hasIndicator ?ind . ?ind rdfs:label ?indLabel . }
  FILTER (
    lcase(str(?indName)) = "private default rate" ||
    lcase(str(?indLabel)) = "private default rate" ||
    EXISTS { ?obs rdf:type gemr:PrivateDefaultRate }
  )

  BIND(IF(?yearNum = 2010, xsd:decimal(?value), UNDEF) AS ?v2010)
  BIND(IF(?yearNum = 2020, xsd:decimal(?value), UNDEF) AS ?v2020)
}
GROUP BY ?countryName

