WHERE {
  ?stockObs rdf:type gemr:Observation ;
            rdf:type gemr:StockMarketPerformance ;
            gemr:hasCountry ?country ;
            gemr:hasYear ?stockYearNode ;
            gemr:observationValue ?stockValue .
  ?country gemr:countryName ?countryName .
  FILTER(?countryName IN ("Brazil","China","Mexico","Philippines","Poland","Thailand"))
  ?stockYearNode gemr:yearValue ?stockYear .
  BIND(xsd:integer(?stockYear) AS ?stockYearInt)
  FILTER(?stockYearInt >= 2002 && ?stockYearInt <= 2022)
  BIND(?stockYearInt + 1 AS ?nextYearInt)

  ?gdpObs rdf:type gemr:Observation ;
          rdf:type gemr:RealGDPGrowth ;
          gemr:hasCountry ?country ;
          gemr:hasYear ?gdpYearNode ;
