WHERE {
  ?stockObs a gemr:Observation ;
            gemr:hasCountry ?country ;
            gemr:hasIndicator gemr:StockMarket ;
            gemr:hasYear ?stockYearEntity ;
            gemr:observationValue ?stockValue .

  ?country gemr:countryName ?countryName .
  ?stockYearEntity gemr:yearValue ?stockYearLit .
  BIND(xsd:integer(STR(?stockYearLit)) AS ?stockYear)

  BIND(?stockYear + 1 AS ?defaultYearInt)
  ?defaultYearEntity gemr:yearValue ?defaultYearLit .
  FILTER(xsd:integer(STR(?defaultYearLit)) = ?defaultYearInt)

  ?defaultObs a gemr:Observation ;
              gemr:hasCountry ?country ;
              gemr:hasIndicator gemr:PrivateDefaultRate ;
              gemr:hasYear ?defaultYearEntity ;
              gemr:observationValue ?defaultRateValue .
}
