PREFIX gemr: <https://gemr-kg.org/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryName ?year ((((?currentGDP - ?previousGDP) / ?previousGDP) * 100) AS ?growthRate)
WHERE {
  ?obsCurrent a gemr:Observation ;
              gemr:hasCountry ?country ;
              gemr:hasIndicator gemr:GDP_at_market_prices_current_US ;
              gemr:hasYear ?yearEntityCurrent ;
              gemr:observationValue ?currentGDP .

  ?country gemr:countryName ?countryName .
  ?yearEntityCurrent gemr:yearValue ?yearCurrent .
  BIND(xsd:integer(STR(?yearCurrent)) AS ?yearIntCurrent)

  BIND(?yearIntCurrent - 1 AS ?yearIntPrevious)
  ?yearEntityPrevious gemr:yearValue ?yearPrevious .
  FILTER(xsd:integer(STR(?yearPrevious)) = ?yearIntPrevious)

  ?obsPrevious a gemr:Observation ;
               gemr:hasCountry ?country ;
               gemr:hasIndicator gemr:GDP_at_market_prices_current_US ;
               gemr:hasYear ?yearEntityPrevious ;
               gemr:observationValue ?previousGDP .

  FILTER(?previousGDP != 0)
  BIND(STR(?yearCurrent) AS ?year)
}
ORDER BY ?countryName ?year

